from __future__ import annotations

import py_compile
import shutil
import sys
from datetime import datetime
from pathlib import Path

VISION_FILE = 'from __future__ import annotations\n\nimport base64\nimport random\nimport re\nfrom io import BytesIO\nfrom typing import Any\n\nimport httpx\nfrom PIL import Image, ImageOps\n\nfrom app.config import Settings\nfrom app.services.chat import route_chat\n\n\nIMAGE_MIME_TYPES = {\n    "image/jpeg",\n    "image/png",\n    "image/webp",\n    "image/gif",\n}\nSUPPORTED_MIME_TYPES = IMAGE_MIME_TYPES | {"application/pdf"}\n\nVISION_SYSTEM_PROMPT = """You are Vasuki Vision, a careful multimodal assistant.\nInspect the supplied image or document directly and answer in the user\'s language.\n\nAccuracy rules:\n1. Read every visible word, number, symbol, table, diagram and option carefully.\n2. Never invent text hidden by blur, cropping, glare or low resolution. Clearly mark unreadable portions.\n3. For question sheets, answer every visible question in the same order. Include question numbers, selected options and necessary calculations or reasoning.\n4. For maths and science, re-check arithmetic, units, signs and final answers.\n5. For screenshots, forms, bills, charts and documents, preserve the visible structure and terminology.\n6. For normal photos, describe only what is actually visible and then answer the user\'s specific question.\n7. Do not identify unknown real people by name from their face.\n"""\n\nEDIT_PATTERNS = (\n    r"\\bedit\\b",\n    r"\\bmodify\\b",\n    r"\\bretouch\\b",\n    r"\\benhance\\b",\n    r"\\bupscale\\b",\n    r"\\brestore\\b",\n    r"\\brecolor\\b",\n    r"\\bcrop\\b",\n    r"\\bremove\\b",\n    r"\\breplace\\b",\n    r"\\badd\\b",\n    r"\\banime\\b",\n    r"\\bcartoon\\b",\n    r"\\b4k\\b",\n    r"\\bhd\\b",\n    r"\\bgora\\b",\n    r"\\bgori\\b",\n    r"background\\s+(change|remove|replace|hata|badal)",\n    r"(rang|colour|color)\\s+(change|badal)",\n    r"(kapde|dress|hair|baal)\\s+(change|badal)",\n    r"(photo|image|picture)\\s+ko\\s+(change|edit|saaf|clear|gora)",\n)\n\n\ndef _safe_error(response: httpx.Response) -> str:\n    try:\n        payload = response.json()\n        if isinstance(payload, dict):\n            error = payload.get("error")\n            if isinstance(error, dict) and error.get("message"):\n                return str(error["message"])[:700]\n            for key in ("message", "detail", "errors"):\n                if payload.get(key):\n                    return str(payload[key])[:700]\n    except Exception:\n        pass\n    return (response.text or f"HTTP {response.status_code}")[:700]\n\n\ndef _looks_like_edit(prompt: str) -> bool:\n    normalized = prompt.casefold().strip()\n    return any(re.search(pattern, normalized) for pattern in EDIT_PATTERNS)\n\n\ndef _analysis_prompt(user_prompt: str) -> str:\n    prompt = user_prompt.strip() or "Is image/file ko detail me analyze karo."\n    return (\n        f"{prompt}\\n\\n"\n        "Apply the Vasuki Vision accuracy rules. If this is a question paper, "\n        "worksheet or answer sheet, solve every visible question in order and "\n        "do not skip any readable item."\n    )\n\n\ndef _edit_prompt(user_prompt: str) -> str:\n    prompt = user_prompt.strip() or "Enhance this image naturally."\n    return (\n        "Edit input image 0 according to this instruction: "\n        f"{prompt}. Preserve the original person\'s identity, facial structure, "\n        "pose and important details unless the instruction explicitly asks to "\n        "change them. Keep lighting, edges and perspective realistic. Do not add "\n        "unrequested people, text, logos or objects. Return only the edited image."\n    )\n\n\ndef _extract_gemini_text(payload: dict[str, Any]) -> str:\n    candidates = payload.get("candidates") or []\n    if not candidates:\n        return ""\n\n    parts = candidates[0].get("content", {}).get("parts", [])\n    return "".join(\n        str(part.get("text") or "")\n        for part in parts\n        if isinstance(part, dict)\n    ).strip()\n\n\ndef _find_image_block(value: Any) -> tuple[str, str] | None:\n    if isinstance(value, dict):\n        data = value.get("data")\n        mime = value.get("mime_type") or value.get("mimeType")\n        block_type = str(value.get("type") or "").casefold()\n        if isinstance(data, str) and data and (\n            isinstance(mime, str) and mime.startswith("image/")\n            or "image" in block_type\n        ):\n            return data, str(mime or "image/png")\n\n        for item in value.values():\n            found = _find_image_block(item)\n            if found:\n                return found\n\n    if isinstance(value, list):\n        for item in value:\n            found = _find_image_block(item)\n            if found:\n                return found\n\n    return None\n\n\nasync def _gemini_analyze(\n    content: bytes,\n    mime_type: str,\n    prompt: str,\n    settings: Settings,\n) -> dict:\n    if not settings.google_gemini_api:\n        raise RuntimeError("Google Gemini vision is not configured")\n\n    model = settings.gemini_vision_model\n    url = (\n        "https://generativelanguage.googleapis.com/v1beta/models/"\n        f"{model}:generateContent"\n    )\n    payload = {\n        "systemInstruction": {\n            "parts": [{"text": VISION_SYSTEM_PROMPT}],\n        },\n        "contents": [\n            {\n                "role": "user",\n                "parts": [\n                    {\n                        "inlineData": {\n                            "mimeType": mime_type,\n                            "data": base64.b64encode(content).decode("ascii"),\n                        }\n                    },\n                    {"text": _analysis_prompt(prompt)},\n                ],\n            }\n        ],\n        "generationConfig": {\n            "maxOutputTokens": min(settings.max_output_tokens, 8192),\n        },\n    }\n    headers = {\n        "x-goog-api-key": settings.google_gemini_api,\n        "Content-Type": "application/json",\n    }\n\n    async with httpx.AsyncClient(\n        timeout=float(settings.vision_timeout_seconds)\n    ) as client:\n        response = await client.post(url, headers=headers, json=payload)\n\n    if response.is_error:\n        raise RuntimeError(\n            f"Gemini vision HTTP {response.status_code}: {_safe_error(response)}"\n        )\n\n    answer = _extract_gemini_text(response.json())\n    if not answer:\n        raise RuntimeError("Gemini vision returned an empty answer")\n\n    return {\n        "answer": answer,\n        "provider": f"gemini-vision:{model}",\n        "operation": "analyze",\n    }\n\n\n\ndef _extract_cloudflare_text(value: Any) -> str:\n    if isinstance(value, str):\n        return value.strip()\n\n    if isinstance(value, dict):\n        for key in (\n            "answer",\n            "response",\n            "text",\n            "caption",\n            "description",\n            "output_text",\n            "content",\n        ):\n            candidate = value.get(key)\n            extracted = _extract_cloudflare_text(candidate)\n            if extracted:\n                return extracted\n\n        choices = value.get("choices")\n        if isinstance(choices, list):\n            for choice in choices:\n                extracted = _extract_cloudflare_text(choice)\n                if extracted:\n                    return extracted\n\n        message = value.get("message")\n        extracted = _extract_cloudflare_text(message)\n        if extracted:\n            return extracted\n\n    if isinstance(value, list):\n        parts = [_extract_cloudflare_text(item) for item in value]\n        return "\\n".join(part for part in parts if part).strip()\n\n    return ""\n\n\ndef _prepare_analysis_image(content: bytes) -> tuple[bytes, str]:\n    try:\n        with Image.open(BytesIO(content)) as source:\n            image = ImageOps.exif_transpose(source).convert("RGB")\n            image.thumbnail((1800, 1800), Image.Resampling.LANCZOS)\n\n            best = b""\n            for quality in (92, 86, 80, 74, 68, 60):\n                buffer = BytesIO()\n                image.save(\n                    buffer,\n                    format="JPEG",\n                    quality=quality,\n                    optimize=True,\n                )\n                encoded = buffer.getvalue()\n                best = encoded\n                if len(encoded) <= 1_300_000:\n                    break\n\n            return best, "image/jpeg"\n    except Exception:\n        return content, "image/jpeg"\n\n\ndef _prepare_ocr_upload(\n    content: bytes,\n    mime_type: str,\n) -> tuple[bytes, str, str]:\n    free_limit = 1_400_000\n\n    if len(content) <= free_limit:\n        return content, mime_type, "upload"\n\n    if mime_type not in IMAGE_MIME_TYPES:\n        raise RuntimeError(\n            "OCR.Space free plan accepts files up to about 1.5 MB. "\n            "This PDF is larger, so Gemini Vision must handle it."\n        )\n\n    try:\n        with Image.open(BytesIO(content)) as source:\n            image = ImageOps.exif_transpose(source).convert("RGB")\n            image.thumbnail((2400, 2400), Image.Resampling.LANCZOS)\n\n            smallest = b""\n            while True:\n                for quality in (90, 84, 78, 72, 66, 58, 50):\n                    buffer = BytesIO()\n                    image.save(\n                        buffer,\n                        format="JPEG",\n                        quality=quality,\n                        optimize=True,\n                    )\n                    encoded = buffer.getvalue()\n                    smallest = encoded\n                    if len(encoded) <= free_limit:\n                        return encoded, "image/jpeg", "compressed-ocr.jpg"\n\n                width, height = image.size\n                if max(width, height) <= 1200:\n                    break\n                image = image.resize(\n                    (\n                        max(800, int(width * 0.82)),\n                        max(800, int(height * 0.82)),\n                    ),\n                    Image.Resampling.LANCZOS,\n                )\n\n            if smallest and len(smallest) <= 1_500_000:\n                return smallest, "image/jpeg", "compressed-ocr.jpg"\n    except Exception as exc:\n        raise RuntimeError(\n            "The image could not be compressed for OCR.Space."\n        ) from exc\n\n    raise RuntimeError(\n        "The image is still too large for OCR.Space free plan after "\n        "safe compression."\n    )\n\n\nasync def _cloudflare_analyze(\n    content: bytes,\n    mime_type: str,\n    prompt: str,\n    settings: Settings,\n) -> dict:\n    if not settings.cloudflare_account_id or not settings.cloudflare_workers_ai:\n        raise RuntimeError("Cloudflare Workers AI vision is not configured")\n    if mime_type not in IMAGE_MIME_TYPES:\n        raise RuntimeError("Cloudflare vision fallback only supports images")\n\n    model = settings.cloudflare_vision_model\n    if not model.startswith("@cf/"):\n        model = f"@cf/{model.lstrip(\'/\')}"\n\n    url = (\n        "https://api.cloudflare.com/client/v4/accounts/"\n        f"{settings.cloudflare_account_id}/ai/run/{model}"\n    )\n    prepared_content, prepared_mime = _prepare_analysis_image(content)\n    image_data = (\n        f"data:{prepared_mime};base64,"\n        + base64.b64encode(prepared_content).decode("ascii")\n    )\n    payload = {\n        "task": "query",\n        "image": image_data,\n        "question": VISION_SYSTEM_PROMPT + "\\n\\n" + _analysis_prompt(prompt),\n        "reasoning": False,\n        "temperature": 0.1,\n        "max_tokens": min(settings.max_output_tokens, 8192),\n        "stream": False,\n    }\n    headers = {\n        "Authorization": f"Bearer {settings.cloudflare_workers_ai}",\n        "Content-Type": "application/json",\n    }\n\n    async with httpx.AsyncClient(\n        timeout=float(settings.vision_timeout_seconds)\n    ) as client:\n        response = await client.post(url, headers=headers, json=payload)\n\n    if response.is_error:\n        raise RuntimeError(\n            f"Cloudflare vision HTTP {response.status_code}: {_safe_error(response)}"\n        )\n\n    payload = response.json()\n    result = payload.get("result") or payload\n    answer = _extract_cloudflare_text(result)\n\n    if not answer:\n        retry_payload = {\n            "task": "query",\n            "image": image_data,\n            "question": (\n                "Read this image carefully. Answer the user\'s request in the "\n                "same language. Do not skip readable questions. USER REQUEST: "\n                + (prompt.strip() or "Describe and analyze this image.")\n            ),\n            "reasoning": True,\n            "temperature": 0.0,\n            "max_tokens": min(settings.max_output_tokens, 4096),\n            "stream": False,\n        }\n        async with httpx.AsyncClient(\n            timeout=float(settings.vision_timeout_seconds)\n        ) as client:\n            retry_response = await client.post(\n                url,\n                headers=headers,\n                json=retry_payload,\n            )\n\n        if retry_response.is_error:\n            raise RuntimeError(\n                "Cloudflare vision retry HTTP "\n                f"{retry_response.status_code}: {_safe_error(retry_response)}"\n            )\n\n        retry_json = retry_response.json()\n        retry_result = retry_json.get("result") or retry_json\n        answer = _extract_cloudflare_text(retry_result)\n\n    if not answer:\n        compact_payload = str(payload)[:900]\n        raise RuntimeError(\n            "Cloudflare vision returned an empty answer. "\n            f"Response preview: {compact_payload}"\n        )\n\n    return {\n        "answer": answer,\n        "provider": f"cloudflare-vision:{model}",\n        "operation": "analyze",\n    }\n\n\nasync def _ocr_space_text(\n    content: bytes,\n    filename: str,\n    mime_type: str,\n    settings: Settings,\n) -> str:\n    if not settings.ocr_space_api:\n        raise RuntimeError("OCR.Space is not configured")\n\n    upload_content, upload_mime, upload_name = _prepare_ocr_upload(\n        content,\n        mime_type,\n    )\n    files = {\n        "file": (\n            upload_name if upload_name != "upload" else (filename or "upload"),\n            upload_content,\n            upload_mime or "application/octet-stream",\n        )\n    }\n    data = {\n        "apikey": settings.ocr_space_api,\n        "language": "eng",\n        "isOverlayRequired": "false",\n        "OCREngine": "2",\n    }\n\n    async with httpx.AsyncClient(\n        timeout=float(settings.vision_timeout_seconds)\n    ) as client:\n        response = await client.post(\n            "https://api.ocr.space/parse/image",\n            data=data,\n            files=files,\n        )\n\n    if response.is_error:\n        raise RuntimeError(\n            f"OCR.Space HTTP {response.status_code}: {_safe_error(response)}"\n        )\n\n    payload = response.json()\n    parsed = payload.get("ParsedResults") or []\n    text = "\\n".join(\n        str(item.get("ParsedText") or "")\n        for item in parsed\n        if isinstance(item, dict)\n    ).strip()\n    if not text:\n        raise RuntimeError(\n            f"OCR.Space returned no readable text: {payload.get(\'ErrorMessage\')}"\n        )\n    return text\n\n\nasync def _ocr_then_chat(\n    content: bytes,\n    filename: str,\n    mime_type: str,\n    prompt: str,\n    settings: Settings,\n) -> dict:\n    text = await _ocr_space_text(\n        content,\n        filename,\n        mime_type,\n        settings,\n    )\n    messages = [\n        {\n            "role": "user",\n            "content": (\n                VISION_SYSTEM_PROMPT\n                + "\\n\\nUSER REQUEST:\\n"\n                + _analysis_prompt(prompt)\n                + "\\n\\nOCR TEXT:\\n"\n                + text[:35000]\n            ),\n        }\n    ]\n    answer, provider = await route_chat(\n        "auto",\n        messages,\n        settings,\n        require_current=False,\n    )\n    return {\n        "answer": answer,\n        "provider": f"ocr.space+{provider}",\n        "operation": "analyze",\n    }\n\n\ndef _prepare_cloudflare_image(content: bytes) -> tuple[bytes, int, int]:\n    try:\n        with Image.open(BytesIO(content)) as source:\n            image = ImageOps.exif_transpose(source).convert("RGB")\n            original_width, original_height = image.size\n\n            input_image = image.copy()\n            input_image.thumbnail((511, 511), Image.Resampling.LANCZOS)\n            input_buffer = BytesIO()\n            input_image.save(input_buffer, format="JPEG", quality=92)\n\n            scale = min(1024 / original_width, 1024 / original_height)\n            width = max(256, min(1920, round(original_width * scale / 64) * 64))\n            height = max(256, min(1920, round(original_height * scale / 64) * 64))\n            return input_buffer.getvalue(), width, height\n    except Exception as exc:\n        raise RuntimeError("The uploaded image could not be decoded") from exc\n\n\nasync def _cloudflare_edit(\n    content: bytes,\n    prompt: str,\n    settings: Settings,\n) -> dict:\n    if not settings.cloudflare_account_id or not settings.cloudflare_workers_ai:\n        raise RuntimeError("Cloudflare image editing is not configured")\n\n    model = settings.cloudflare_edit_model\n    if not model.startswith("@cf/"):\n        model = f"@cf/{model.lstrip(\'/\')}"\n\n    prepared, width, height = _prepare_cloudflare_image(content)\n    url = (\n        "https://api.cloudflare.com/client/v4/accounts/"\n        f"{settings.cloudflare_account_id}/ai/run/{model}"\n    )\n    headers = {\n        "Authorization": f"Bearer {settings.cloudflare_workers_ai}",\n    }\n    data = {\n        "prompt": _edit_prompt(prompt),\n        "width": str(width),\n        "height": str(height),\n        "guidance": "4.0",\n        "seed": str(random.randint(1, 2_147_483_647)),\n    }\n    files = {\n        "input_image_0": ("input.jpg", prepared, "image/jpeg"),\n    }\n\n    async with httpx.AsyncClient(\n        timeout=float(settings.vision_timeout_seconds)\n    ) as client:\n        response = await client.post(\n            url,\n            headers=headers,\n            data=data,\n            files=files,\n        )\n\n    if response.is_error:\n        raise RuntimeError(\n            f"Cloudflare edit HTTP {response.status_code}: {_safe_error(response)}"\n        )\n\n    payload = response.json()\n    result = payload.get("result") or {}\n    image_b64 = result.get("image") if isinstance(result, dict) else None\n    if not isinstance(image_b64, str) or not image_b64:\n        raise RuntimeError("Cloudflare edit response did not contain an image")\n\n    return {\n        "answer": "Edited image ready.",\n        "url": f"data:image/png;base64,{image_b64}",\n        "provider": f"cloudflare-edit:{model}",\n        "operation": "edit",\n    }\n\n\nasync def _gemini_edit(\n    content: bytes,\n    mime_type: str,\n    prompt: str,\n    settings: Settings,\n) -> dict:\n    if not settings.google_gemini_api:\n        raise RuntimeError("Gemini image editing is not configured")\n\n    model = settings.gemini_image_edit_model\n    url = (\n        "https://generativelanguage.googleapis.com/v1beta/models/"\n        f"{model}:generateContent"\n    )\n    headers = {\n        "x-goog-api-key": settings.google_gemini_api,\n        "Content-Type": "application/json",\n    }\n    payload = {\n        "contents": [\n            {\n                "role": "user",\n                "parts": [\n                    {"text": _edit_prompt(prompt)},\n                    {\n                        "inlineData": {\n                            "mimeType": mime_type,\n                            "data": base64.b64encode(content).decode("ascii"),\n                        }\n                    },\n                ],\n            }\n        ],\n        "generationConfig": {\n            "responseModalities": ["TEXT", "IMAGE"],\n            "responseFormat": {\n                "image": {\n                    "imageSize": "1K",\n                }\n            },\n        },\n    }\n\n    async with httpx.AsyncClient(\n        timeout=float(settings.vision_timeout_seconds)\n    ) as client:\n        response = await client.post(url, headers=headers, json=payload)\n\n    if response.is_error:\n        raise RuntimeError(\n            f"Gemini edit HTTP {response.status_code}: {_safe_error(response)}"\n        )\n\n    found = _find_image_block(response.json())\n    if not found:\n        raise RuntimeError("Gemini edit response did not contain an image")\n\n    image_b64, output_mime = found\n    return {\n        "answer": "Edited image ready.",\n        "url": f"data:{output_mime};base64,{image_b64}",\n        "provider": f"gemini-edit:{model}",\n        "operation": "edit",\n    }\n\n\nasync def process_vision_request(\n    *,\n    content: bytes,\n    filename: str,\n    mime_type: str,\n    prompt: str,\n    operation: str,\n    settings: Settings,\n) -> dict:\n    normalized_mime = (mime_type or "").split(";", 1)[0].strip().casefold()\n    if normalized_mime == "image/jpg":\n        normalized_mime = "image/jpeg"\n\n    if normalized_mime not in SUPPORTED_MIME_TYPES:\n        raise RuntimeError(\n            "Unsupported file type. Upload JPG, PNG, WEBP, GIF or PDF."\n        )\n\n    normalized_operation = (operation or "auto").strip().casefold()\n    if normalized_operation not in {"auto", "analyze", "edit"}:\n        raise RuntimeError("operation must be auto, analyze or edit")\n\n    should_edit = (\n        normalized_operation == "edit"\n        or (\n            normalized_operation == "auto"\n            and normalized_mime in IMAGE_MIME_TYPES\n            and _looks_like_edit(prompt)\n        )\n    )\n\n    errors: list[str] = []\n\n    if should_edit:\n        for name, provider in (\n            ("cloudflare", _cloudflare_edit),\n            ("gemini", _gemini_edit),\n        ):\n            try:\n                if name == "cloudflare":\n                    return await provider(content, prompt, settings)\n                return await provider(content, normalized_mime, prompt, settings)\n            except Exception as exc:\n                errors.append(f"{name}: {str(exc)[:700]}")\n\n        raise RuntimeError(\n            "Image editing failed. " + " | ".join(errors)\n        )\n\n    analyzers = [\n        ("gemini", _gemini_analyze),\n    ]\n    if normalized_mime in IMAGE_MIME_TYPES:\n        analyzers.append(("cloudflare", _cloudflare_analyze))\n\n    for name, analyzer in analyzers:\n        try:\n            return await analyzer(\n                content,\n                normalized_mime,\n                prompt,\n                settings,\n            )\n        except Exception as exc:\n            errors.append(f"{name}: {str(exc)[:700]}")\n\n    try:\n        return await _ocr_then_chat(\n            content,\n            filename,\n            normalized_mime,\n            prompt,\n            settings,\n        )\n    except Exception as exc:\n        errors.append(f"ocr: {str(exc)[:700]}")\n\n    raise RuntimeError(\n        "Image/file analysis failed. " + " | ".join(errors)\n    )\n'


def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8-sig")


def write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")


def replace_all(content: str, replacements: list[tuple[str, str]]) -> str:
    for old, new in replacements:
        content = content.replace(old, new)
    return content


def main() -> int:
    root = (
        Path(sys.argv[1]).expanduser().resolve()
        if len(sys.argv) > 1
        else Path.cwd().resolve()
    )

    vision = root / "backend" / "app" / "services" / "vision.py"
    config = root / "backend" / "app" / "config.py"
    chat = root / "backend" / "app" / "services" / "chat.py"
    env = root / "backend" / ".env.example"

    for path in (vision, config, chat, env):
        if not path.exists():
            raise RuntimeError(f"Required file not found: {path}")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = root / f"vision-provider-fix-backup-{stamp}"

    for path in (vision, config, chat, env):
        destination = backup / path.relative_to(root)
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    write_text(vision, VISION_FILE)

    config_text = replace_all(
        read_text(config),
        [
            (
                'gemini_model: str = "gemini-2.5-flash"',
                'gemini_model: str = "gemini-3.6-flash"',
            ),
            (
                'gemini_vision_model: str = "gemini-2.5-flash"',
                'gemini_vision_model: str = "gemini-3.6-flash"',
            ),
        ],
    )
    write_text(config, config_text)

    env_text = replace_all(
        read_text(env),
        [
            ("GEMINI_MODEL=gemini-2.5-flash", "GEMINI_MODEL=gemini-3.6-flash"),
            (
                "GEMINI_VISION_MODEL=gemini-2.5-flash",
                "GEMINI_VISION_MODEL=gemini-3.6-flash",
            ),
        ],
    )
    write_text(env, env_text)

    chat_text = read_text(chat)
    old_block = """            "generationConfig": {
                "temperature": temperature,
                "maxOutputTokens": settings.max_output_tokens,
            },
"""
    new_block = """            "generationConfig": {
                "maxOutputTokens": settings.max_output_tokens,
            },
"""
    if old_block in chat_text:
        chat_text = chat_text.replace(old_block, new_block, 1)
    write_text(chat, chat_text)

    for path in (vision, config, chat):
        py_compile.compile(str(path), doraise=True)

    print("\nVision provider fix completed successfully.\n")
    print("[UPDATED] backend/app/services/vision.py")
    print("[UPDATED] backend/app/config.py")
    print("[UPDATED] backend/app/services/chat.py")
    print("[UPDATED] backend/.env.example")
    print(f"\nBackup created at:\n{backup}")
    print(
        "\nNext commands:\n"
        "git add backend/app/services/vision.py backend/app/config.py "
        "backend/app/services/chat.py backend/.env.example\n"
        'git commit -m "Fix Gemini vision and OCR fallback"\n'
        "git push\n"
    )
    print(
        "IMPORTANT: In Render Environment set both values to gemini-3.6-flash:\n"
        "GEMINI_MODEL\n"
        "GEMINI_VISION_MODEL\n"
    )
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"\nFIX FAILED: {exc}", file=sys.stderr)
        raise SystemExit(1)
